package com.lexorion.workforce.service;
import static com.lexorion.workforce.api.ResourceDtos.*;import com.lexorion.workforce.api.WorkforceException;import com.lexorion.workforce.domain.*;import com.lexorion.workforce.repository.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;
@Service public class ReferenceService {private final WorkspaceScope scope;private final DepartmentRepository departments;private final DesignationRepository designations;private final EmployeeRepository employees;private final OrganizationChangeEventRepository events;public ReferenceService(WorkspaceScope s,DepartmentRepository d,DesignationRepository g,EmployeeRepository e,OrganizationChangeEventRepository v){scope=s;departments=d;designations=g;employees=e;events=v;}
 @Transactional(readOnly=true)public List<Reference> departments(Boolean active,String parentKey,String search){String q=blank(search)?null:search.trim().toLowerCase(Locale.ROOT);String p=keyOrNull(parentKey);return departments.findByWorkspaceIdOrderByNameAsc(scope.context().workspaceId()).stream().filter(d->active==null||(d.getStatus()==ActiveStatus.ACTIVE)==active).filter(d->p==null||(d.getParent()!=null&&d.getParent().getKey().equals(p))).filter(d->q==null||d.getKey().contains(q)||d.getName().toLowerCase(Locale.ROOT).contains(q)).map(Reference::from).toList();}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Reference createDepartment(CreateReference r){var w=scope.lockedWorkspace();String key=key(r.key());if(departments.existsByWorkspaceIdAndKey(w.getId(),key))throw new WorkforceException(409,"Department key already exists");Department d=new Department();d.setWorkspace(w);d.setKey(key);d.setName(name(r.name()));d.setParent(parent(w.getId(),r.parentDepartmentKey(),null));departments.saveAndFlush(d);audit(w,"DEPARTMENT",key,"CREATED",null,d.getParent()==null?null:d.getParent().getKey());return Reference.from(d);}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Reference updateDepartment(String rawKey,UpdateReference r){var w=scope.lockedWorkspace();Department d=findDepartment(w.getId(),rawKey);if(r.name()!=null)d.setName(name(r.name()));if(r.parentDepartmentKeyPresent()){if(d.getStatus()!=ActiveStatus.ACTIVE)throw new WorkforceException(400,"Inactive department hierarchy cannot be changed");Department old=d.getParent();Department next=parent(w.getId(),r.parentDepartmentKey(),d);d.setParent(next);audit(w,"DEPARTMENT",d.getKey(),"PARENT_CHANGED",old==null?null:old.getKey(),next==null?null:next.getKey());}if(r.status()!=null&&r.status()!=d.getStatus()){if(r.status()==ActiveStatus.ACTIVE&&d.getParent()!=null&&d.getParent().getStatus()!=ActiveStatus.ACTIVE)throw new WorkforceException(400,"Department with inactive parent cannot be activated");ActiveStatus old=d.getStatus();d.setStatus(r.status());audit(w,"DEPARTMENT",d.getKey(),r.status()==ActiveStatus.ACTIVE?"ACTIVATED":"DEACTIVATED",old.name(),r.status().name());}return Reference.from(departments.saveAndFlush(d));}
 @Transactional(readOnly=true)public List<Reference> designations(Boolean active,String search){String q=blank(search)?null:search.trim().toLowerCase(Locale.ROOT);return designations.findByWorkspaceIdOrderByNameAsc(scope.context().workspaceId()).stream().filter(d->active==null||(d.getStatus()==ActiveStatus.ACTIVE)==active).filter(d->q==null||d.getKey().contains(q)||d.getName().toLowerCase(Locale.ROOT).contains(q)).map(Reference::from).toList();}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Reference createDesignation(CreateReference r){if(r.parentDepartmentKey()!=null)throw new WorkforceException(400,"Designation cannot have a parent department");var w=scope.lockedWorkspace();String key=key(r.key());if(designations.existsByWorkspaceIdAndKey(w.getId(),key))throw new WorkforceException(409,"Designation key already exists");Designation d=new Designation();d.setWorkspace(w);d.setKey(key);d.setName(name(r.name()));designations.saveAndFlush(d);audit(w,"DESIGNATION",key,"CREATED",null,null);return Reference.from(d);}
 @Transactional(isolation=Isolation.READ_COMMITTED)public Reference updateDesignation(String rawKey,UpdateReference r){if(r.parentDepartmentKeyPresent())throw new WorkforceException(400,"Designation cannot have a parent department");var w=scope.lockedWorkspace();Designation d=designations.findByWorkspaceIdAndKey(w.getId(),key(rawKey)).orElseThrow(()->new WorkforceException(404,"Designation not found"));if(r.name()!=null)d.setName(name(r.name()));if(r.status()!=null&&r.status()!=d.getStatus()){ActiveStatus old=d.getStatus();d.setStatus(r.status());audit(w,"DESIGNATION",d.getKey(),r.status()==ActiveStatus.ACTIVE?"ACTIVATED":"DEACTIVATED",old.name(),r.status().name());}return Reference.from(designations.saveAndFlush(d));}
 @Transactional(readOnly=true)public OrganizationStructureResponse structure(){UUID w=scope.context().workspaceId();var ds=departments.findByWorkspaceIdOrderByNameAsc(w).stream().map(d->new StructureDepartment(d.getKey(),d.getName(),d.getParent()==null?null:d.getParent().getKey(),d.getStatus())).toList();var es=employees.findStructure(w).stream().map(e->new StructureEmployee(e.getCode(),e.getFirstName()+" "+e.getLastName(),e.getDepartment()==null?null:e.getDepartment().getKey(),e.getDesignation()==null?null:e.getDesignation().getKey(),e.getReportingManager()==null?null:e.getReportingManager().getCode(),e.getStatus())).toList();return new OrganizationStructureResponse(ds,es);}
 private Department parent(UUID w,String raw,Department child){if(blank(raw))return null;Department value=findDepartment(w,raw);if(value.getStatus()!=ActiveStatus.ACTIVE)throw new WorkforceException(400,"Inactive department cannot receive child departments");if(child!=null&&value.getId().equals(child.getId()))throw new WorkforceException(409,"Department cannot be its own parent");Set<UUID> seen=new HashSet<>();for(Department p=value;p!=null;p=p.getParent()){if(!seen.add(p.getId())||(child!=null&&p.getId().equals(child.getId())))throw new WorkforceException(409,"Department hierarchy cycle rejected");}return value;}
 private Department findDepartment(UUID w,String raw){return departments.findByWorkspaceIdAndKey(w,key(raw)).orElseThrow(()->new WorkforceException(404,"Department not found"));}private void audit(WorkforceWorkspace w,String type,String key,String action,String from,String to){events.save(new OrganizationChangeEvent(w,type,key,action,from,to));}private static String key(String v){return v.trim().toLowerCase(Locale.ROOT);}private static String keyOrNull(String v){return blank(v)?null:key(v);}private static String name(String n){String v=n.trim();if(v.isEmpty())throw new WorkforceException(400,"Name must not be blank");return v;}private static boolean blank(String v){return v==null||v.isBlank();}}
